<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref} from 'vue';import {operationMessage,type LocalLauncherClient} from './local-api';import type {GameInstance} from './local-types';import type {PlayerServer,PlayerServersSnapshot,ServerProbeResult} from './resource-types';import './resource-manager.css';
const props=defineProps<{client:LocalLauncherClient;instances:GameInstance[]}>();const emit=defineEmits<{connect:[instanceId:string,server:PlayerServer & {revision:string}]}>();const saved=ref<PlayerServersSnapshot|null>(null),error=ref(''),busy=ref(false),name=ref(''),host=ref(''),port=ref(25565),editing=ref<string|null>(null),removing=ref(''),selected=ref(''),results=ref<Record<string,ServerProbeResult>>({});
const supported=computed(()=>props.instances.filter(i=>i.installation&&['1.20.6','1.21.1'].includes(i.gameVersion)));const controller=new AbortController();let alive=true;
async function work(run:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await run();}catch(e){if(alive)error.value=operationMessage(e);}finally{if(alive)busy.value=false;}}
async function load(){await work(async()=>{const value=await props.client.playerServers(controller.signal);if(alive){saved.value=value;results.value={};}});}
async function save(){if(!saved.value)return;await work(async()=>{const value=await props.client.savePlayerServer(saved.value!.revision,editing.value,name.value,host.value,Number(port.value),controller.signal);if(alive){saved.value=value;results.value={};reset();}});}
function reset(){editing.value=null;name.value='';host.value='';port.value=25565;}
function edit(server:PlayerServer){editing.value=server.id;name.value=server.name;host.value=server.address.host;port.value=server.address.port;}
function probe(server:PlayerServer){void work(async()=>{const value=await props.client.probePlayerServer(server.id,controller.signal);if(alive)results.value={...results.value,[server.id]:value};});}
function remove(){if(!saved.value)return;void work(async()=>{const value=await props.client.removePlayerServer(saved.value!.revision,removing.value,controller.signal);if(alive){saved.value=value;results.value={};removing.value='';}});}
function connect(server:PlayerServer){const id=selected.value||supported.value[0]?.id;if(id)emit('connect',id,{...server,revision:saved.value!.revision});}
onMounted(load);onBeforeUnmount(()=>{alive=false;controller.abort();});
</script>
<template><section class="launcher-local-page player-servers"><div class="launcher-section-heading"><div><span class="launcher-overline">PLAY TOGETHER</span><h1>服务器</h1><p>收藏常用地址，手动检查连接，再通过现有启动检查进入游戏。</p></div><button class="launcher-secondary" :disabled="busy" @click="load">刷新收藏</button></div><p v-if="error" role="alert" class="launcher-inline-notice">{{error}}</p><p v-if="busy" role="status">正在处理…</p>
<form v-if="saved" class="launcher-glass server-form" @submit.prevent="save"><label class="server-form-name">{{editing?'修改收藏':'添加服务器'}}<input data-server-name v-model="name" placeholder="朋友的服务器" maxlength="64" :disabled="busy"/></label><label>主机名或IP<input data-server-host v-model="host" placeholder="play.example.org" maxlength="253" :disabled="busy"/></label><label>端口<input data-server-port v-model.number="port" type="number" min="1" max="65535" :disabled="busy"/></label><button class="launcher-primary" data-server-save :disabled="busy||!name.trim()||!host.trim()">{{editing?'保存修改':'保存收藏'}}</button><button v-if="editing" type="button" :disabled="busy" @click="reset">取消修改</button></form>
<label class="resource-filter">直连使用的实例<select data-server-instance v-model="selected"><option value="">{{supported.length?'自动选择首个可用实例':'请先安装1.20.6或1.21.1实例'}}</option><option v-for="instance in supported" :value="instance.id" :key="instance.id">{{instance.name}} · {{instance.gameVersion}}</option></select></label><p class="launcher-caption">点击检测才会连接该地址；TCP延迟不是游戏内延迟或入服承诺。直连仍需游戏身份、Java和完整安装。</p>
<div v-if="removing" class="resource-confirm launcher-glass"><p>从收藏移除此服务器？不会改游戏存档或服务器数据。</p><button data-server-confirm-remove class="launcher-secondary" :disabled="busy" @click="remove">确认移除收藏</button><button @click="removing=''">取消</button></div>
<article v-for="server in saved?.servers??[]" :key="server.id" :data-player-server="server.id" class="launcher-glass resource-file"><div><h2>{{server.name}}</h2><p>{{server.address.host}} · {{server.address.port}}</p><p v-if="results[server.id]" class="server-connection-result">{{results[server.id]!.state==='REACHABLE'?'端口可达':results[server.id]!.state==='TIMEOUT'?'检测超时':results[server.id]!.state==='MOCK'?'离线示例':'无法连接'}}<span v-if="results[server.id]!.latencyMs!==null"> · {{results[server.id]!.latencyMs}} ms</span><br/>{{results[server.id]!.message}}</p><p v-else class="launcher-caption">尚未检测</p></div><div class="resource-file-actions"><button class="launcher-secondary" :data-server-probe="server.id" :disabled="busy" @click="probe(server)">检测连接</button><button :data-server-connect="server.id" :disabled="busy||!supported.length" @click="connect(server)">启动直连 →</button><button :disabled="busy" @click="edit(server)">编辑</button><button :data-server-remove="server.id" :disabled="busy" @click="removing=server.id">移除收藏</button></div></article><p v-if="saved&&!saved.servers.length&&!busy">还没有服务器收藏。</p></section></template>
